SELECT city, CASE WHEN credit_limit >= 14800 THEN 'LARGE' ELSE 'SMALL' END AS credit_limit_tier, COUNT(CASE WHEN segment = 'Consumer' THEN 1 END) AS consumer_count, COUNT_IF(city = 'Berlin') AS berlin_events, ROUND(AVG(age), 2) AS avg_age, ROUND(AVG(age), 2) AS avg_age_2, COUNT(DISTINCT country) AS distinct_countries, GROUPING(city) AS grouping_level FROM customers GROUP BY CUBE (city, CASE WHEN credit_limit >= 14800 THEN 'LARGE' ELSE 'SMALL' END) HAVING consumer_count < 1 ORDER BY city DESC;
